import * as THREE from 'three';

const TAU = Math.PI * 2;

export function setupActions(root) {
  const mixer = new THREE.AnimationMixer(root);

  // "idle": bob position.y with a sine over 2 seconds (9 keyframes)
  const idleTimes = [];
  const idleValues = [];
  for (let i = 0; i < 9; i++) {
    const t = (i / 8) * 2;
    idleTimes.push(t);
    idleValues.push(0, Math.sin((Math.PI * 2 * t) / 2), 0);
  }
  const idleClip = new THREE.AnimationClip('idle', 2, [
    new THREE.VectorKeyframeTrack('.position', idleTimes, idleValues),
  ]);

  // "spin": one full turn around Y over 1 second
  const q = (angle) => new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0,1,0), angle).toArray();
  const spinClip = new THREE.AnimationClip('spin', 1, [
    new THREE.QuaternionKeyframeTrack('.quaternion', [0, 0.5, 1], [...q(0), ...q(Math.PI), ...q(TAU)]),
  ]);

  const idle = mixer.clipAction(idleClip);
  const spin = mixer.clipAction(spinClip);

  idle.setEffectiveWeight(1);
  spin.setEffectiveWeight(0);
  idle.play();
  spin.play();

  return { mixer, idle, spin };
}

export function crossfade(actions, seconds) {
  actions.spin.crossFadeFrom(actions.idle, seconds);
  return actions;
}

export function stepMixer(state, dt) {
  state.mixer.update(dt);
  return state;
}
